// ViewSubscribeParams `view/subscribe` params (tdd SS4.7.1): attach this connection's live view subscription
// for a session at an explicit cursor — the fine-grained counterpart of the SS2
// auto-subscribe, and the gap-free re-attachment path after `view/unsubscribe`. It never
// loads a session, takes no lease, writes nothing.
type ViewSubscribeParams struct {
	// Resume cursor. When present, the server replays `(after, head]` as ordinary view
	// notifications before any live event — one gapless cursor sequence. Omitted means "from
	// now": no historical replay (tdd SS4.7.1).
	After *string `json:"after,omitempty"`
	// The session to follow.
	SessionID string `json:"sessionId"`
}

// ViewSubscribeResult `view/subscribe` result (tdd SS4.7.1).
type ViewSubscribeResult struct {
	// The view head at subscribe time; the client knows it is live once cursors pass it.
	ViewCursor string `json:"viewCursor"`
}

// ViewUnsubscribeParams `view/unsubscribe` params (tdd SS4.7.2): remove this connection from the session's view
// subscription set — the protocol's single unsubscribe operation, at the altitude that
// owns subscriptions (tdd SS2.5.6 points here). It does not unload the session; unloading
// is the idle policy (tdd SS2.8).
type ViewUnsubscribeParams struct {
	// The session to stop following.
	SessionID string `json:"sessionId"`
}

// ViewUnsubscribeResult `view/unsubscribe` result (tdd SS4.7.2): the empty object. Idempotent — unsubscribing
// while not subscribed returns `{}`.
type ViewUnsubscribeResult struct{}

// WorkflowCancelParams `workflow/cancel` params (tdd SS3.19): cancel a live workflow run.
